package comment

class CommentBottomBarManager(private val slots: PrioritySlots) {
    fun bindDefaultInput() {
        if (slots.isFree("POI_ENTRY")) {
            slots.attachDefaultCommentInput()
        }
    }

    fun onWindowInsets(bottom: Int) {
        slots.container().setPadding(0, 0, 0, bottom)
    }
}

